-- 映射完成后增加约束；旧的未确认关联包含新空键，不参与有效权限。
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_AppsInfo') AND name=N'UX_BackendKind') CREATE UNIQUE INDEX [UX_BackendKind] ON dbo.[tb_Auth_AppsInfo] (AppKind) WHERE IsDeleted=0 AND AppKind=N'Backend';
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_CrudRole') AND name=N'UX_TenantAdministrator') CREATE UNIQUE INDEX [UX_TenantAdministrator] ON dbo.[tb_Auth_CrudRole] (TenantId,AppsId,RoleKind) WHERE IsDeleted=0 AND RoleKind=N'TenantAdministrator';
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Unit_Employee') AND name=N'UX_EmployeeUser') CREATE UNIQUE INDEX [UX_EmployeeUser] ON dbo.[tb_Unit_Employee] (UserId) WHERE IsDeleted=0 AND OwnershipConfirmed=1 AND UserId IS NOT NULL;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_CrudRoleUser') AND name=N'UX_RoleMember') CREATE UNIQUE INDEX [UX_RoleMember] ON dbo.[tb_Auth_CrudRoleUser] (RoleId,UserId) WHERE IsDeleted=0 AND TenantId IS NOT NULL AND AppsId IS NOT NULL;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_CrudRoleCrud') AND name=N'UX_RoleOperation') CREATE UNIQUE INDEX [UX_RoleOperation] ON dbo.[tb_Auth_CrudRoleCrud] (CrudRoleId,CrudInfoId) WHERE IsDeleted=0 AND TenantId IS NOT NULL AND AppsId IS NOT NULL;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_CrudInfo') AND name=N'UX_AppOperationCode') CREATE UNIQUE INDEX [UX_AppOperationCode] ON dbo.[tb_Auth_CrudInfo] (AppsId,CrudCode) WHERE IsDeleted=0 AND NodeType=N'Operation';
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_User') AND name=N'UX_tb_Auth_User_Scope') CREATE UNIQUE INDEX [UX_tb_Auth_User_Scope] ON dbo.[tb_Auth_User] (Id,TenantId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Unit_Department') AND name=N'UX_tb_Unit_Department_Scope') CREATE UNIQUE INDEX [UX_tb_Unit_Department_Scope] ON dbo.[tb_Unit_Department] (Id,TenantId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_CrudRole') AND name=N'UX_tb_Auth_CrudRole_Scope') CREATE UNIQUE INDEX [UX_tb_Auth_CrudRole_Scope] ON dbo.[tb_Auth_CrudRole] (Id,TenantId,AppsId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_CrudInfo') AND name=N'UX_tb_Auth_CrudInfo_Scope') CREATE UNIQUE INDEX [UX_tb_Auth_CrudInfo_Scope] ON dbo.[tb_Auth_CrudInfo] (Id,AppsId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_CrudRoleCrud') AND name=N'UX_tb_Auth_CrudRoleCrud_Scope') CREATE UNIQUE INDEX [UX_tb_Auth_CrudRoleCrud_Scope] ON dbo.[tb_Auth_CrudRoleCrud] (Id,TenantId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_User') AND name=N'IX_tb_Auth_User_Scope') CREATE INDEX [IX_tb_Auth_User_Scope] ON dbo.[tb_Auth_User] (TenantId,IsDeleted,IsActived);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Unit_Employee') AND name=N'IX_tb_Unit_Employee_Scope') CREATE INDEX [IX_tb_Unit_Employee_Scope] ON dbo.[tb_Unit_Employee] (TenantId,DepartmentId,UserId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_LoginSession') AND name=N'IX_tb_Auth_LoginSession_Scope') CREATE INDEX [IX_tb_Auth_LoginSession_Scope] ON dbo.[tb_Auth_LoginSession] (UserId,RevokedAt,ExpiresAt);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_TenantContext') AND name=N'IX_tb_Auth_TenantContext_Scope') CREATE INDEX [IX_tb_Auth_TenantContext_Scope] ON dbo.[tb_Auth_TenantContext] (SessionId,UserId,TenantId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_AuditEvent') AND name=N'IX_tb_Auth_AuditEvent_Scope') CREATE INDEX [IX_tb_Auth_AuditEvent_Scope] ON dbo.[tb_Auth_AuditEvent] (TenantId,CreatedAt);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Auth_AuditOutbox') AND name=N'IX_tb_Auth_AuditOutbox_Scope') CREATE INDEX [IX_tb_Auth_AuditOutbox_Scope] ON dbo.[tb_Auth_AuditOutbox] (DispatchedAt,CreatedAt);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Bzss_Company') AND name=N'IX_tb_Bzss_Company_Scope') CREATE INDEX [IX_tb_Bzss_Company_Scope] ON dbo.[tb_Bzss_Company] (TenantId,OwnerUserId,OwnerDepartmentId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.tb_Bzss_Project') AND name=N'IX_tb_Bzss_Project_Scope') CREATE INDEX [IX_tb_Bzss_Project_Scope] ON dbo.[tb_Bzss_Project] (TenantId,OwnerUserId,OwnerDepartmentId);
IF OBJECT_ID(N'dbo.FK_EmployeeUserTenant',N'F') IS NULL ALTER TABLE dbo.tb_Unit_Employee WITH CHECK ADD CONSTRAINT FK_EmployeeUserTenant FOREIGN KEY(UserId,TenantId) REFERENCES dbo.tb_Auth_User(Id,TenantId);
IF OBJECT_ID(N'dbo.FK_EmployeeDepartmentTenant',N'F') IS NULL ALTER TABLE dbo.tb_Unit_Employee WITH CHECK ADD CONSTRAINT FK_EmployeeDepartmentTenant FOREIGN KEY(DepartmentId,TenantId) REFERENCES dbo.tb_Unit_Department(Id,TenantId);
IF OBJECT_ID(N'dbo.FK_CompanyOwner',N'F') IS NULL ALTER TABLE dbo.tb_Bzss_Company WITH CHECK ADD CONSTRAINT FK_CompanyOwner FOREIGN KEY(OwnerUserId,TenantId) REFERENCES dbo.tb_Auth_User(Id,TenantId);
IF OBJECT_ID(N'dbo.FK_CompanyDepartment',N'F') IS NULL ALTER TABLE dbo.tb_Bzss_Company WITH CHECK ADD CONSTRAINT FK_CompanyDepartment FOREIGN KEY(OwnerDepartmentId,TenantId) REFERENCES dbo.tb_Unit_Department(Id,TenantId);
IF OBJECT_ID(N'dbo.FK_ProjectOwner',N'F') IS NULL ALTER TABLE dbo.tb_Bzss_Project WITH CHECK ADD CONSTRAINT FK_ProjectOwner FOREIGN KEY(OwnerUserId,TenantId) REFERENCES dbo.tb_Auth_User(Id,TenantId);
IF OBJECT_ID(N'dbo.FK_ProjectDepartment',N'F') IS NULL ALTER TABLE dbo.tb_Bzss_Project WITH CHECK ADD CONSTRAINT FK_ProjectDepartment FOREIGN KEY(OwnerDepartmentId,TenantId) REFERENCES dbo.tb_Unit_Department(Id,TenantId);
IF OBJECT_ID(N'dbo.FK_RoleUserRoleTenantApp',N'F') IS NULL ALTER TABLE dbo.tb_Auth_CrudRoleUser WITH CHECK ADD CONSTRAINT FK_RoleUserRoleTenantApp FOREIGN KEY(RoleId,TenantId,AppsId) REFERENCES dbo.tb_Auth_CrudRole(Id,TenantId,AppsId);
IF OBJECT_ID(N'dbo.FK_RoleUserUserTenant',N'F') IS NULL ALTER TABLE dbo.tb_Auth_CrudRoleUser WITH CHECK ADD CONSTRAINT FK_RoleUserUserTenant FOREIGN KEY(UserId,TenantId) REFERENCES dbo.tb_Auth_User(Id,TenantId);
IF OBJECT_ID(N'dbo.FK_GrantRoleTenantApp',N'F') IS NULL ALTER TABLE dbo.tb_Auth_CrudRoleCrud WITH CHECK ADD CONSTRAINT FK_GrantRoleTenantApp FOREIGN KEY(CrudRoleId,TenantId,AppsId) REFERENCES dbo.tb_Auth_CrudRole(Id,TenantId,AppsId);
IF OBJECT_ID(N'dbo.FK_GrantInfoApp',N'F') IS NULL ALTER TABLE dbo.tb_Auth_CrudRoleCrud WITH CHECK ADD CONSTRAINT FK_GrantInfoApp FOREIGN KEY(CrudInfoId,AppsId) REFERENCES dbo.tb_Auth_CrudInfo(Id,AppsId);
IF OBJECT_ID(N'dbo.FK_GrantDepartmentGrant',N'F') IS NULL ALTER TABLE dbo.tb_Auth_GrantDepartment WITH CHECK ADD CONSTRAINT FK_GrantDepartmentGrant FOREIGN KEY(GrantId,TenantId) REFERENCES dbo.tb_Auth_CrudRoleCrud(Id,TenantId);
IF OBJECT_ID(N'dbo.FK_GrantDepartmentTenant',N'F') IS NULL ALTER TABLE dbo.tb_Auth_GrantDepartment WITH CHECK ADD CONSTRAINT FK_GrantDepartmentTenant FOREIGN KEY(DepartmentId,TenantId) REFERENCES dbo.tb_Unit_Department(Id,TenantId);
IF OBJECT_ID(N'dbo.CK_ReadyUserIdentity',N'C') IS NULL ALTER TABLE dbo.tb_Auth_User WITH CHECK ADD CONSTRAINT CK_ReadyUserIdentity CHECK(SecurityReady=0 OR (SecurityVersion>=1 AND ((IsAdmin=1 AND TenantId IS NULL) OR (IsAdmin=0 AND TenantId IS NOT NULL AND TenantId>0))));
IF OBJECT_ID(N'dbo.CK_ConfirmedEmployee',N'C') IS NULL ALTER TABLE dbo.tb_Unit_Employee WITH CHECK ADD CONSTRAINT CK_ConfirmedEmployee CHECK(OwnershipConfirmed=0 OR TenantId IS NOT NULL);
IF OBJECT_ID(N'dbo.CK_ConfirmedCompany',N'C') IS NULL ALTER TABLE dbo.tb_Bzss_Company WITH CHECK ADD CONSTRAINT CK_ConfirmedCompany CHECK(OwnershipConfirmed=0 OR (TenantId IS NOT NULL AND OwnerUserId IS NOT NULL));
IF OBJECT_ID(N'dbo.CK_ConfirmedProject',N'C') IS NULL ALTER TABLE dbo.tb_Bzss_Project WITH CHECK ADD CONSTRAINT CK_ConfirmedProject CHECK(OwnershipConfirmed=0 OR (TenantId IS NOT NULL AND OwnerUserId IS NOT NULL));
